      this.slotsAvialbleItems = [];
      const startTime = {
        hours: 9,
        minutes: 0
      };
      const endTime = {
        hours: 24,
        minutes: 0
      };
      let currentTime = {
        ...startTime
      };
      while (currentTime.hours < endTime.hours || currentTime.hours === endTime.hours && currentTime.minutes === endTime.minutes) {
        const label = `${currentTime.hours.toString().padStart(2, "0")}:${currentTime.minutes === 0 ? "00" : "30"}`;
        this.slotsAvialbleItems.push({
          text: label,
          value: label
        });

